text = await CONTEXT.read(0, 52180)
# Let me look at all the shell commands the agent ran
for i in range(1, 21):
    idx = text.find(f"[tool {i}]")
    if idx >= 0:
        end_idx = text.find(f"\n[result {i}]", idx)
        if end_idx < 0:
            end_idx = idx + 500
        snippet = text[idx:end_idx]
        # Only print the command, not the full content
        if "shell" in snippet:
            # Extract just the command
            cmd_start = snippet.find('"command": "')
            if cmd_start >= 0:
                cmd_end = snippet.find('"', cmd_start + 12)
                if cmd_end >= 0:
                    cmd = snippet[cmd_start+12:cmd_end]
                    print(f"Tool {i}: {cmd[:200]}")
                else:
                    print(f"Tool {i}: [long command]")
            else:
                print(f"Tool {i}: [shell command]")
        elif "read_file" in snippet:
            print(f"Tool {i}: read_file")
        elif "write_file" in snippet:
            print(f"Tool {i}: write_file")
        elif "git_diff" in snippet:
            print(f"Tool {i}: git_diff")
        elif "list_dir" in snippet:
            print(f"Tool {i}: list_dir")
        elif "search" in snippet:
            print(f"Tool {i}: search")
        else:
            print(f"Tool {i}: {snippet[:100]}")
